SELECT event_type, CASE WHEN duration_sec >= 464 THEN 'high' WHEN duration_sec >= 155 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, SUM(CASE WHEN event_type = 'page_view' THEN 1 ELSE 0 END) AS page_view_count FROM web_events GROUP BY event_type, CASE WHEN duration_sec >= 464 THEN 'high' WHEN duration_sec >= 155 THEN 'mid' ELSE 'low' END HAVING SUM(CASE WHEN event_type = 'page_view' THEN 1 ELSE 0 END) >= 36;
